package vn.hust.restaurant.view;
import java.awt.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.*;import vn.hust.restaurant.model.*;
public class KitchenPanel extends JPanel implements Refreshable{private final AppContext ctx;private final UserSession session;private final DefaultTableModel model=Ui.model("ID","Order","Bàn - Món","SL","Ghi chú","Trạng thái");private final JTable table=new JTable(model);private java.util.List<OrderItemView>data=java.util.List.of();private final javax.swing.Timer timer;public KitchenPanel(AppContext c,UserSession s){ctx=c;session=s;setLayout(new BorderLayout());JButton start=new JButton("Bắt đầu làm"),done=new JButton("Hoàn thành"),reload=new JButton("Làm mới");add(Ui.toolbar(start,done,reload,new JLabel("Tự cập nhật mỗi 1,5 giây")),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);start.addActionListener(e->change("DANG_LAM"));done.addActionListener(e->change("DA_XONG"));reload.addActionListener(e->refresh());timer=new javax.swing.Timer(AppConfig.appInt("kitchen.refresh.ms",1500),e->refresh());timer.start();refresh();}
 private void change(String status){int r=table.getSelectedRow();if(r<0)return;Ui.run(this,()->{ctx.kitchen.status(data.get(r).id(),status,session.employeeId());refresh();});}public void refresh(){Ui.run(this,()->{data=ctx.kitchen.queue();model.setRowCount(0);for(OrderItemView x:data)model.addRow(new Object[]{x.id(),x.orderId(),x.menuItemName(),x.quantity(),x.note(),x.kitchenStatus()});});}}
